{
  "items": [
    {
      "name": "MvPolynomial.weightedHomogeneousComponent_apply",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R) [inst_2 : DecidableEq M],\n  (MvPolynomial.weightedHomogeneousComponent w n) φ =\n    ∑ d ∈ φ.support with (Finsupp.weight w) d = n, (MvPolynomial.monomial d) (MvPolynomial.coeff d φ)"
    },
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.prod",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {ι : Type u_4}\n  (s : Finset ι) (φ : ι → MvPolynomial σ R) (n : ι → M) {w : σ → M},\n  (∀ i ∈ s, MvPolynomial.IsWeightedHomogeneous w (φ i) (n i)) →\n    MvPolynomial.IsWeightedHomogeneous w (∏ i ∈ s, φ i) (∑ i ∈ s, n i)"
    },
    {
      "name": "MvPowerSeries.weightedHomogeneousComponent_mul_of_le_weightedOrder",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {w : σ → ℕ} {f g : MvPowerSeries σ R} {p q : ℕ},\n  ↑p ≤ MvPowerSeries.weightedOrder w f →\n    ↑q ≤ MvPowerSeries.weightedOrder w g →\n      (MvPowerSeries.weightedHomogeneousComponent w (p + q)) (f * g) =\n        (MvPowerSeries.weightedHomogeneousComponent w p) f * (MvPowerSeries.weightedHomogeneousComponent w q) g"
    },
    {
      "name": "MvPolynomial.weightedHomogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {M : Type u_2} →\n    [inst : CommSemiring R] → {σ : Type u_3} → [AddCommMonoid M] → (σ → M) → M → MvPolynomial σ R →ₗ[R] MvPolynomial σ R"
    },
    {
      "name": "MvPowerSeries.IsWeightedHomogeneous.mul",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {R : Type u_2} [inst : Semiring R] {w : σ → ℕ} {f g : MvPowerSeries σ R} {p q : ℕ},\n  MvPowerSeries.IsWeightedHomogeneous w f p →\n    MvPowerSeries.IsWeightedHomogeneous w g q → MvPowerSeries.IsWeightedHomogeneous w (f * g) (p + q)"
    }
  ]
}
